def sembol(k, don, ic):
    if don: ic = f'<g transform="rotate(45 12 12)">{ic}</g>'
    return f'<symbol id="e-{k}" viewBox="0 0 24 24">{ic}</symbol>'

if __name__ == '__main__':
    import sys
    syms = ''.join(sembol(*x) for x in HEPSI)
    cells = ''.join(f'<div><svg class="ic"><use href="#e-{k}"/></svg><span>{k}</span></div>' for k, _, _ in HEPSI)
    html = f'''<!doctype html><meta charset="utf-8"><style>
body{{background:#1b1a1f;color:#e9dfc8;font:11px sans-serif;margin:10px;display:grid;grid-template-columns:repeat(12,1fr);gap:6px}}
div{{display:flex;flex-direction:column;align-items:center;gap:3px;border:1px solid #333;padding:6px}}
.ic{{width:48px;height:48px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;color:#f0c46a}}
</style><svg width="0" height="0" style="position:absolute">{syms}</svg>{cells}'''
    open(sys.argv[1], 'w', encoding='utf-8').write(html)
    print(len(HEPSI), 'ikon', len(syms), 'karakter')
